 * tool-quality-scan — JS cron handler for tool failure feedback loop.
 *
 * Scans evaluations DB for failure chains from the last 24h, classifies
 * each failure into categories (empty-args, wrong-tool, nonexistent-path,
 * edit-match-fail, schema-violation, path-is-directory), aggregates by
 * tool × issue × agent, compares against baseline, and writes a report.
 *
 * If any category regresses >20% vs baseline, injects a focused task
 * into optimizer's todo.
 *
 * Pure JS — no LLM cost. Runs every 4h via cron.
 *
 * Exports create() conforming to HandlerModule.
 */

import { existsSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { getDb } from "../../../src/lib/requests.js";
import type { HandlerContext, HandlerModule } from "../../../src/lib/handler-context.js";
import type { CronEntry } from "../../../src/lib/cron-tool.js";

// ── Types ─────────────────────────────────────────────────────────────

export type FailureCategory =
  | "empty-args" | "wrong-tool" | "nonexistent-path" | "edit-match-fail"
  | "schema-violation" | "path-is-directory" | "convention-block" | "other";

interface FailureChain {
  trigger: { tool: string; args: string; result: string; isError?: boolean };

/**
 * error-log-scanner — JS cron handler (Stage 3 graduation).
 *
 * Scans all agents ERROR_LOG files for repeated error patterns.
 * If any agent has ≥3 errors of the same type in the last 7 days,
 * triggers Coach with a focused growth-cycle message.
 * If no agents meet the threshold → no-op (zero LLM cost).
 *
 * Exports create() conforming to HandlerModule.
 */

import { readdirSync, readFileSync, existsSync, statSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { HandlerContext, HandlerModule } from "../../../src/lib/handler-context.js";
import type { CronEntry } from "../../../src/lib/cron-tool.js";

// ── Configuration ─────────────────────────────────────────────────────

/** Minimum repeated errors of the same type to trigger a growth cycle. */
const ERROR_THRESHOLD = 3;

/** How far back to look (7 days in milliseconds). */
const LOOKBACK_MS = 7 * 24 * 60 * 60 * 1000;

/** Cooldown period — don't re-trigger same (agent, errorType) within this window.
 *  Matches LOOKBACK_MS so patterns only re-trigger when new errors occur outside the window. */
const COOLDOWN_MS = 7 * 24 * 60 * 60 * 1000; // 7 days (matches lookback window)

/** Maximum growth-trigger sessions to launch per scan cycle. */
const MAX_TRIGGERS_PER_SCAN = 3;

/** Minimum ceiling/skipped-ceiling experiments for an agent before we suppress triggers. */
const EXPERIMENTS_CEILING_THRESHOLD = 3;

/** How far back to look in experiments history (14 days in milliseconds). */
const EXPERIMENTS_LOOKBACK_MS = 14 * 24 * 60 * 60 * 1000;

// ── Experiments-history gate ──────────────────────────────────────────

/**
 * Check if an agent has enough recent CEILING / skipped-ceiling
 * experiments that further growth-trigger cycles would be wasteful.
 *
 * Returns `{ skip: true, reason }` when the agent has ≥3 such results
 * in the last 14 days; otherwise `{ skip: false, reason: "" }`.
 */
export function checkExperimentsHistory(
  agentsRoot: string,
  agent: string,
): { skip: boolean; reason: string } {
  const experimentsPath = join(agentsRoot, "coach", "workspace", "experiments.jsonl");

  if (!existsSync(experimentsPath)) {
    return { skip: false, reason: "" };
  }

  let content: string;
  try {
    content = readFileSync(experimentsPath, "utf-8");
  } catch {
    return { skip: false, reason: "" };
  }

  const now = Date.now();
  const cutoff = now - EXPERIMENTS_LOOKBACK_MS;
  let ceilingCount = 0;

  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;

    let entry: Record<string, unknown>;
    try {
      entry = JSON.parse(trimmed);
    } catch {
      continue;
    }

    // Agent must match
    if (entry.agent !== agent) continue;

    // Check recency — support both "date" (YYYY-MM-DD) and "timestamp" (ISO)
    let entryTime: number;
    if (typeof entry.date === "string") {
      entryTime = new Date(entry.date).getTime();
    } else if (typeof entry.timestamp === "string") {
      entryTime = new Date(entry.timestamp).getTime();
    } else {
      continue; // No date info — skip
    }
    if (isNaN(entryTime) || entryTime < cutoff) continue;

    // Match: result is "CEILING", or decision "skipped" with ceiling reason
    const result = typeof entry.result === "string" ? entry.result : "";
    const decision = typeof entry.decision === "string" ? entry.decision : "";
    const reason = typeof entry.reason === "string" ? entry.reason : "";

    const isCeiling = result === "CEILING";
    const isSkippedCeiling =
      (result === "skipped" || decision === "skipped") &&
      reason.toLowerCase().includes("ceiling");

    if (isCeiling || isSkippedCeiling) {
      ceilingCount++;
    }
  }

  if (ceilingCount >= EXPERIMENTS_CEILING_THRESHOLD) {
    return {
      skip: true,
      reason: `Agent "${agent}" has ${ceilingCount} ceiling/skipped-ceiling experiments in the last 14 days — likely at ceiling`,
